import React, { useState } from 'react';
import Reservas from './Reservas'; // Importamos el componente con la tabla

const AdminPanel = () => {
  const [activeTab, setActiveTab] = useState('Reservas');

  return (
    <div style={{ display: 'flex', minHeight: '100vh' }}>
      <aside className="sidebar">
        <div className="sidebar-header">
          <h2>Capitania Admin</h2>
        </div>
        <ul className="nav-menu">
          {['Reservas', 'Eventos', 'Promociones'].map((tab) => (
            <li 
              key={tab}
              className={`nav-item ${activeTab === tab ? 'active' : ''}`}
              onClick={() => setActiveTab(tab)}
            >
              {tab}
            </li>
          ))}
        </ul>
      </aside>

      <main className="main-content">
        <div className="topbar">
          <h1>{activeTab}</h1>
          <button className="btn-logout" onClick={() => window.location.href = '/login'}>Cerrar Sesión</button>
        </div>

        <div className="dashboard-content">
          {/* Aquí es donde aparece el contenido real */}
          {activeTab === 'Reservas' && <Reservas />}
          {activeTab !== 'Reservas' && <p>Sección de {activeTab} en desarrollo.</p>}
        </div>
      </main>
    </div>
  );
};

export default AdminPanel;
